                         ((y[i] > 0 && y[j] > 0) || (y[i] < 0 && y[j] < 0)))
                    k = (abs(x[i]) + abs(x[j])) * abs(y[i] - y[j]);
                else if (y[i] > 0 && y[j] < 0 &&
                         ((x[i] > 0 && x[j] > 0) || (x[i] < 0 || x[j] < 0)))
                    k = abs(x[i] - x[j]) * (abs(y[i]) + abs(y[j]));
                else
                    k = (x[i] - x[j]) * (y[i] - y[j]);

                res = max(res, k);

                if (x[j] > 0 && x[i] < 0 && y[j] > 0 && y[i] < 0)
                    k = (abs(x[j]) + abs(x[i])) * (abs(y[j]) + abs(y[i]));
                else if (x[j] > 0 && x[i] < 0 &&
                         ((y[j] > 0 && y[i] > 0) || (y[j] < 0 && y[i] < 0)))
                    k = (abs(x[j]) + abs(x[i])) * abs(y[j] - y[i]);
                else if (y[j] > 0 && y[i] < 0 &&
                         ((x[j] > 0 && x[i] > 0) || (x[j] < 0 || x[i] < 0)))
                    k = abs(x[j] - x[i]) * (abs(y[j]) + abs(y[i]));
                else
                    k = (x[j] - x[i]) * (y[j] - y[i]);

                res = max(res, k);
            }
        }

        cout << (res > 0 ? res : -1) << '\n';
    }

    return 0;
}

